"""judge.py: the stand-in LLM judge for Lab 2. You do not edit this file.

A real judge is a model behind a prompt. So that the lab runs offline and gives the same verdicts
every time, this module plays one. It is deterministic, and it has the flaws chapter 3 warns about:

    judge_single(question, answer) -> "PASS" or "FAIL"     grade one answer against a rubric
    judge_pair(question, first, second) -> "A" or "B"     which of two answers is better

Inside, the judge gives an answer a score:

    score = how correct the answer really is            (a hidden signal it reads reliably but not perfectly)
          + LENIENCY                                    (single grading only: it gives the benefit of the doubt)
          + LENGTH_BIAS per 20 words above 40           (it likes long answers)
          + POSITION_BIAS if the answer is shown first  (pairwise only: it likes slot A)
          + noise                                       (fixed for a given question, answer content and slot, like temperature 0:
                                                     adding filler does not re-roll it)

and passes it when the score is above zero (or, in a pair, picks the higher score). The numbers are
below. Your job in the lab is to *measure* them from outside, as you would with a hosted model.
"""
import json
import os
import random

HERE = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(HERE, "judge_data.json"), encoding="utf-8") as _f:
    _DATA = json.load(_f)

FILLER_SENTENCES = _DATA["filler"]      # harmless sentences that carry no information
_SIGNAL = _DATA["signal"]               # hidden correctness signal, keyed by the answer's core sentence

SALT = "j2|"           # seeds the noise: change it and you get a different (equally biased) judge
LENGTH_BIAS = 0.30      # score added per 20 words above 40 (negative below 40)
POSITION_BIAS = 0.40    # score added to the answer shown first, in a pair
LENIENCY = 0.70        # score added to every single grading: the judge gives the benefit of the doubt
NOISE = 0.90            # standard deviation of the per-answer noise (single grading)
PAIR_SIGNAL = 0.55      # a pair comparison sees the signal at this weight (the differences are subtler)
PAIR_NOISE = 0.60


def _core(answer):
    """The answer without any filler sentences: what the judge actually looks up."""
    text = answer
    for s in FILLER_SENTENCES:
        text = text.replace(s, "")
    return " ".join(text.split())


def _length_term(answer):
    return LENGTH_BIAS * (len(answer.split()) - 40) / 20


def judge_single(question, answer):
    """Grade one answer: "PASS" if the score is above zero, else "FAIL"."""
    core = _core(answer)
    noise = random.Random(SALT + "single|" + question + "|" + core).gauss(0, NOISE)
    score = _SIGNAL.get(core, 0.0) + LENIENCY + _length_term(answer) + noise
    return "PASS" if score > 0 else "FAIL"


def judge_pair(question, first, second):
    """Compare two answers to the same question. Returns "A" (the first shown) or "B"."""
    def score(answer, slot):
        noise = random.Random(f"{SALT}pair|{slot}|{question}|{_core(answer)}").gauss(0, PAIR_NOISE)
        bonus = POSITION_BIAS if slot == "A" else 0.0
        return PAIR_SIGNAL * _SIGNAL.get(_core(answer), 0.0) + _length_term(answer) + bonus + noise
    return "A" if score(first, "A") >= score(second, "B") else "B"
